package org.example.strategy_pattern.demo;import java.util.HashMap;import java.util.Map;public class PriceCalculator {    private final Map<String, PromotionStrategy> strategies = new HashMap<>();    {        strategies.put("preorder", new PreOrderStrategy());        strategies.put("promotion", new PromotionStrategyImpl());        strategies.put("blackfriday", new BlackFridayStrategy());        strategies.put("default", new NoDiscountStrategy());    }    public double calculatePrice(double originalPrice, String promotionType) {        PromotionStrategy strategy = strategies.getOrDefault(promotionType, strategies.get("default"));        return strategy.applyDiscount(originalPrice);    }    public interface PromotionStrategy {        double applyDiscount(double originalPrice);    }    public static class PreOrderStrategy implements PromotionStrategy {        public double applyDiscount(double originalPrice) {            return originalPrice * 0.9;        }    }    public static class PromotionStrategyImpl implements PromotionStrategy {        public double applyDiscount(double originalPrice) {            return originalPrice * 0.8;        }    }    public static class BlackFridayStrategy implements PromotionStrategy {        public double applyDiscount(double originalPrice) {            return originalPrice * 0.1;        }    }    public static class NoDiscountStrategy implements PromotionStrategy {        public double applyDiscount(double originalPrice) {            return originalPrice;        }    }}